{"function": "() => {
    const articles = [];
    // Find the main article container
    const articleEl = document.querySelector('article');
    if (!articleEl) return [];
    // Find all top-level list items within article
    const topLevelLists = articleEl.querySelectorAll('ul');
    // We'll walk through the DOM structure
    // The structure: each ARTICLE heading is a listitem with text, then nested ul with rule items
    const allLis = articleEl.querySelectorAll('li');
    let currentArticle = null;
    for (let li of allLis) {
        const text = li.textContent.trim();
        // Check if this li's text starts with ARTICLE and includes Roman numeral
        if (text.startsWith('ARTICLE')) {
            // Clean the name: take only up to the next word maybe
            const lines = text.split('\n');
            const firstLine = lines[0].trim();
            // Extract article name
            currentArticle = {
                name: firstLine,
                rules: []
            };
            articles.push(currentArticle);
        } else if (currentArticle) {
            // Check if this li contains a rule link (anchor with href containing 'rule_')
            const link = li.querySelector('a[href*="rule_"]');
            if (link) {
                const ruleText = li.textContent.trim();
                currentArticle.rules.push(ruleText);
            }
        }
    }
    // Filter out articles without rules (the duplicate ones)
    const filtered = articles.filter(a => a.rules.length > 0);
    return filtered;
}"}

