    const articleRegex = /(ARTICLE [A-Z]+\. [^\n]+)/g;
    const articles = [];
    let lastIndex = 0;
    let match;
    let prevArticle = null;
    while ((match = articleRegex.exec(fullText)) !== null) {
        if (prevArticle) {
            // Extract rules between previous article start and this article start
            const ruleText = fullText.substring(prevArticle.start, match.index);
            const ruleLines = ruleText.split('\n').map(l => l.trim()).filter(l => l.startsWith('Rule'));
